import{c as l,Q as a,j as e,m as s}from"./chunks/framework.DOi4mjdC.js";const n="/assets/zh-cn_image_0000002413944550.Cyz2eccg.png",o="/assets/zh-cn_image_0000002414101622.BpBRkT1U.png",i="/assets/%E6%9C%AA%E5%BC%80%E5%90%AFUnitFlag%E5%8A%9F%E8%83%BD.CibimNQI.png",p="/assets/%E5%BC%80%E5%90%AFUnitFlag%E5%8A%9F%E8%83%BD.BFjC4-3P.png",r="/assets/zh-cn_image_0000002413945226.Bkf7Wp1C.png",g="/assets/zh-cn_image_0000002447501485.FDpuUsBu.png",_=JSON.parse('{"title":"Matmul高阶API使能UnitFlag","description":"","frontmatter":{},"headers":[{"level":1,"title":"Matmul高阶API使能UnitFlag","slug":"matmul高阶api使能unitflag"},{"level":2,"title":"案例介绍","slug":"案例介绍"},{"level":2,"title":"获取性能数据","slug":"获取性能数据"},{"level":2,"title":"分析主要瓶颈点","slug":"分析主要瓶颈点"},{"level":2,"title":"设计优化方案","slug":"设计优化方案"},{"level":2,"title":"验证优化方案性能收益","slug":"验证优化方案性能收益"},{"level":2,"title":"总结","slug":"总结"}],"relativePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能UnitFlag.md","filePath":"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能UnitFlag.md"}'),u={name:"guide/算子实践参考/优秀实践/Matmul性能调优案例/Matmul高阶API使能UnitFlag.md"};function c(d,t,m,h,q,M){return a(),e("div",null,[...t[0]||(t[0]=[s('<h1 id="matmul高阶api使能unitflag" tabindex="-1">Matmul高阶API使能UnitFlag <a class="header-anchor" href="#matmul高阶api使能unitflag" aria-label="Permalink to &quot;Matmul高阶API使能UnitFlag&quot;">​</a></h1><h2 id="案例介绍" tabindex="-1">案例介绍 <a class="header-anchor" href="#案例介绍" aria-label="Permalink to &quot;案例介绍&quot;">​</a></h2><p>本案例呈现了在矩阵乘算子场景中，使用Matmul高阶API进行矩阵乘法计算，使能UnitFlag功能对算子性能的提升效果。UnitFlag功能为AIC核中MMAD计算指令和FIXPIPE数据搬运指令提供了基于内存访问的细粒度同步，使计算与搬运流水并行。使能UnitFlag功能的方式为将MatmulConfig中的enUnitFlag参数设置为true。enUnitFlag参数的详细介绍请参考<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/MatmulConfig.md" target="_blank" rel="noreferrer">MatmulConfig</a>。</p><ul><li><p>使能UnitFlag的适用场景</p><p>算子的MMAD流水和FIXPIPE流水之间串行执行，FIXPIPE等待MMAD计算完成才搬出结果，这个指令同步等待的时间在算子整体执行耗时中占比较高。这种场景可以使能UnitFlag功能，以获得MMAD和FIXPIPE流水并行的性能收益。如果算子原本的MMAD、FIXPIPE流水可以被其他流水掩盖（比如MTE2 Bound），这时使能UnitFlag功能总体收益很小。</p></li><li><p>使能UnitFlag的约束条件</p><ul><li>UnitFlag功能仅支持Norm、IBShare、MDL三个模板。</li><li>使能UnitFlag功能时，不支持算子内同时存在CO1(L0C)搬出到Global Memory和A1(L1)搬出到Global Memory的两种流水。</li><li>使能UnitFlag功能时，若同时使能<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Iterate.md" target="_blank" rel="noreferrer">L0C累加</a>功能，不支持多次<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/Iterate.md" target="_blank" rel="noreferrer">Iterate</a>计算、一次<a href="https://gitcode.com/cann/asc-devkit/blob/master/docs/api/context/GetTensorC.md" target="_blank" rel="noreferrer">GetTensorC</a>输出。</li></ul></li></ul><p>本案例的算子规格如下：</p><p><strong>表 1</strong> 算子规格</p><p>&lt;table&gt;&lt;thead align=&quot;left&quot;&gt;&lt;tr&gt;&lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;输入&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Shape&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Data type&lt;/p&gt; &lt;/th&gt; &lt;th class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;Format&lt;/p&gt; &lt;/th&gt; &lt;/tr&gt; &lt;/thead&gt; &lt;tbody&gt;&lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;a&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;128, 64&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;tr&gt;&lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;b&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;64, 30720&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;float16&lt;/p&gt; &lt;/td&gt; &lt;td class=&quot;cellrowborder&quot; valign=&quot;top&quot; width=&quot;25%&quot;&gt;&lt;p&gt;ND&lt;/p&gt; &lt;/td&gt; &lt;/tr&gt; &lt;/tbody&gt; &lt;/table&gt;</p><p>当前案例使用的AI处理器共20个核，每个核包含1个AIC核和2个AIV核。</p><p>算子的Tiling参数如下：</p><ul><li><p>原始shape：M=128, N=30720, K=64。</p></li><li><p>单核shape：按20个AIC核进行切分，singleCoreM=128，singleCoreN=1536，singleCoreK=64。</p><p>对于B矩阵，沿着N轴进行切分，切分成20份singleCoreN，单核上处理K * SingleCoreN大小的数据。对于A矩阵，M轴不进行切分即singleCoreM=M，单核上处理singleCoreM * K大小的数据。总共20个核参与计算。</p></li><li><p>基本块shape：baseM=128，baseN=256，baseK=64。</p></li><li><p>L1相关Tiling参数：stepM=1，stepN=1，stepKa=4，stepKb=4，depthA1=8，depthB1=8。</p></li></ul><h2 id="获取性能数据" tabindex="-1">获取性能数据 <a class="header-anchor" href="#获取性能数据" aria-label="Permalink to &quot;获取性能数据&quot;">​</a></h2><p>使用msProf工具获取<a href="./../../性能分析/获取性能数据.html#section17259539153513">算子仿真流水图</a>和<a href="./../../性能分析/获取性能数据.html#section17953123893415">上板Profiling</a>数据。因为UnitFlag功能主要优化MMAD和FIXPIPE流水串行问题，所以获取性能数据后重点分析Cube、FIXPIPE的流水情况。</p><h2 id="分析主要瓶颈点" tabindex="-1">分析主要瓶颈点 <a class="header-anchor" href="#分析主要瓶颈点" aria-label="Permalink to &quot;分析主要瓶颈点&quot;">​</a></h2><ul><li><p>优化前的流水图如下。如下图中红框所示，每一轮MMAD计算流水和FIXPIPE数据搬出流水之间都是串行执行的，完成MMAD计算后才开始FIXPIPE数据搬出，考虑实现MMAD与FIXPIPE之间流水并行来优化算子性能。</p><p><img src="'+n+'" alt=""></p></li><li><p>优化前的Profiling数据如下，从C列的aic_time数据可以看出，多个核中最大算子执行耗时为37.39us。</p><p><img src="'+o+'" alt=""></p></li></ul><h2 id="设计优化方案" tabindex="-1">设计优化方案 <a class="header-anchor" href="#设计优化方案" aria-label="Permalink to &quot;设计优化方案&quot;">​</a></h2><p>如下图所示，未开启UnitFlag功能时，MMAD和FIXPIPE是指令级别的同步，FIXPIPE指令需要等MMAD指令执行完成才进行结果搬出，MMAD和FIXPIPE之间流水串行。</p><p><strong>图 1</strong> 未开启UnitFlag功能<br><img src="'+i+'" alt="" title="未开启UnitFlag功能"></p><p>如下图所示，开启UnitFlag功能时，MMAD和FIXPIPE指令是512B大小的细粒度同步。在一条MMAD指令执行过程中，每当完成一个512B数据结果的计算，FIXPIPE立即开始搬出该512B的数据，从而实现MMAD和FIXPIPE之间的流水并行，提升算子性能。</p><p><strong>图 2</strong> 开启UnitFlag功能<br><img src="'+p+`" alt="" title="开启UnitFlag功能"></p><p>Matmul API使能UnitFlag功能的完整样例请参考<a href="https://gitcode.com/cann/asc-devkit/tree/master/examples/01_simd_cpp_api/03_libraries/00_matrix/matmul_unitflag" target="_blank" rel="noreferrer">使能UnitFlag功能和MDL模板的Mamtul样例</a>。使能UnitFlag功能的主要步骤如下：</p><ol><li><p>自定义MatmulConfig模板参数，将其中的enUnitFlag参数设置为true，使能UnitFlag功能。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>__aicore__ inline constexpr MatmulConfig GetCustomMDLCFG()</span></span>
<span class="line"><span>{</span></span>
<span class="line"><span>    auto mmCfg = CFG_MDL;</span></span>
<span class="line"><span>    mmCfg.enUnitFlag = true;</span></span>
<span class="line"><span>    return mmCfg;</span></span>
<span class="line"><span>}</span></span>
<span class="line"><span>constexpr static MatmulConfig CUSTOM_CFG_MDL = GetCustomMDLCFG();</span></span></code></pre></div></li><li><p>基于自定义的MatmulConfig模板参数，创建Matmul对象。</p><div class="language- vp-adaptive-theme"><button title="Copy Code" class="copy"></button><span class="lang"></span><pre class="shiki shiki-themes github-light github-dark vp-code" tabindex="0"><code><span class="line"><span>using A_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, AType&gt;;</span></span>
<span class="line"><span>using B_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, BType&gt;;</span></span>
<span class="line"><span>using C_TYPE = AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, CType&gt;;</span></span>
<span class="line"><span>using BIAS_TYPE =  AscendC::MatmulType&lt;AscendC::TPosition::GM, CubeFormat::ND, BiasType&gt;;</span></span>
<span class="line"><span>AscendC::Matmul&lt;A_TYPE, B_TYPE, C_TYPE, BIAS_TYPE, CUSTOM_CFG_MDL &gt; matmulObj;</span></span></code></pre></div></li></ol><h2 id="验证优化方案性能收益" tabindex="-1">验证优化方案性能收益 <a class="header-anchor" href="#验证优化方案性能收益" aria-label="Permalink to &quot;验证优化方案性能收益&quot;">​</a></h2><ul><li><p>优化后的流水图如下，MMAD计算流水和FIXPIPE数据搬出流水之间实现了流水并行。</p><p><img src="`+r+'" alt=""></p></li><li><p>优化后的Profiling数据如下，从C列的aic_time数据可以看出，多个核中最大算子执行耗时为34.66us，较优化前的37.39us有约7.3%的性能提升。</p><p><img src="'+g+'" alt=""></p></li></ul><h2 id="总结" tabindex="-1">总结 <a class="header-anchor" href="#总结" aria-label="Permalink to &quot;总结&quot;">​</a></h2><p>在算子的MMAD计算流水和FIXPIPE数据搬出流水串行且未被其他流水掩盖（比如MTE2 Bound）时，考虑使能UnitFlag功能，实现MMAD计算流水和FIXPIPE数据搬出流水的流水并行，提升算子性能。</p>',25)])])}const F=l(u,[["render",c]]);export{_ as __pageData,F as default};
